// =========================================================================
// Route capability denial (ACs 4, 5) — Co-host and Billing-Admin → 403
// =========================================================================

#[Test]
public function cohost_gets_403_at_route_layer(): void
{
    // events.publish.team is Admin-only; Co-host lacks this capability.
    [$admin, $team] = $this->adminWithPlan(PlanTier::GROWTH);
    $cohost = User::factory()->create(['email_verified_at' => now()]);
    $cohost->teams()->attach($team, ['role' => UserRole::CO_HOST->value]);
    $cohost->forceFill(['current_team_id' => $team->id])->save();

    $event = $this->draftEventForAdmin($admin);

    $response = $this->actingAs($cohost->fresh())->postJson($this->publishUrl($event));

    $response->assertStatus(403);
}

#[Test]
public function billing_admin_gets_403_at_route_layer(): void
{
    // events.publish.team is Admin-only; Billing-Admin lacks this capability.
    [$admin, $team] = $this->adminWithPlan(PlanTier::GROWTH);
    $billingAdmin = User::factory()->create(['email_verified_at' => now()]);
    $billingAdmin->teams()->attach($team, ['role' => UserRole::BILLING_ADMIN->value]);
    $billingAdmin->forceFill(['current_team_id' => $team->id])->save();

    $event = $this->draftEventForAdmin($admin);

    $response = $this->actingAs($billingAdmin->fresh())->postJson($this->publishUrl($event));

    $response->assertStatus(403);
}

